<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Grupy';?>
<div class="page-head"><div><p class="eyebrow">Administracja</p><h1>Grupy</h1></div><a class="button secondary" href="<?=Html::e(Url::to('/admin/users'))?>">Użytkownicy</a></div><?php if(isset($_GET['error'])):?><div class="alert danger">Nie udało się utworzyć grupy.</div><?php endif;?>
<section class="card section-card"><h2>Dodaj grupę</h2><form method="post" class="inline-review-form"><?=Csrf::field()?><label>Nazwa techniczna<input name="name" pattern="[a-z0-9._-]{2,100}" required></label><label>Nazwa wyświetlana<input name="label" maxlength="150" required></label><button class="button">Dodaj</button></form></section>
<section class="card section-card"><h2>Istniejące grupy</h2><?php foreach($groups as $g):?><a class="list-row" href="<?=Html::e(Url::to('/admin/groups/'.$g['id']))?>"><span><strong><?=Html::e($g['label'])?></strong><small><?=Html::e($g['name'])?></small></span><span><?=Html::e($g['member_count'])?> osób</span></a><?php endforeach;?></section>
